using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EnhanceWithNewActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/EnhanceWithNewActionCustomDescription", order = 0)]
public class EnhanceWithNewActionCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		EnhanceWithNewActionAction enhanceWithNewActionAction = battleAction as EnhanceWithNewActionAction;
		string actionName = enhanceWithNewActionAction.NewBattleAction.GetActionName();
		string text = Smart.Format(GetRawLocalizedDescription(battleAction), GetAmountWithoutEquation(amountModified), actionName, enhanceWithNewActionAction.NewActionValueWithoutModifiers);
		if (LanguagesIndexes.IsCurrentLanguageJapanese() && enhanceWithNewActionAction.AddJapaneseVisualBugFix)
		{
			text += "<alpha=#00>JPVisualBugFix";
		}
		return text;
	}

	protected override string GetRawLocalizedDescription(BattleAction battleAction)
	{
		if ((battleAction as EnhanceWithNewActionAction).AnyDice)
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("EnhanceWithNewActionAnyDice");
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(base.CustomActionDescritionID);
	}
}
